var i=`0549-luqaimat`;var n=`world-0549`;var a=`AE`;var r=`western-asia`;var o=8;var l=85;var u={en:`Luqaimat`,ua:`Лукаймат`};var s={en:`A traditional dish from United Arab Emirates, centered on all-purpose flour, instant yeast. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Об'єднані Арабські Емірати. Основні складники: пшеничне борошно універсальне, інстантні дріжджі. Домашній варіант із кількостями продуктів за етапами приготування.`};var d=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:7,i:[[`all-purpose-flour`,230,`g`],[`instant-yeast`,5,`g`],[`white-granulated-sugar`,30,`g`],[`water`,220,`ml`],[`table-salt`,2,`g`]]},{en:`Cool the prepared ingredients promptly, then refrigerate for about 55 minutes until properly chilled.`,ua:`Швидко охолодіть підготовлені складники, потім поставте в холодильник приблизно на 55 хвилин.`,t:[`rapid-chilling`],m:55,i:[]},{en:`Fry shaped portions in small batches in oil heated to about 170–175°C for about 13 minutes, until golden; drain on a rack.`,ua:`Смажте сформовані вироби невеликими партіями в олії температурою приблизно 170–175°C близько 13 хвилин до золотистості; викладіть на решітку.`,t:[`deep-frying`],m:13,i:[[`sunflower-oil`,700,`ml`]]},{en:`Simmer the liquid and flavorings uncovered for about 10 minutes until reduced and concentrated.`,ua:`Уварюйте рідину з приправами без кришки приблизно 10 хвилин до насичення та загустіння.`,t:[`reducing-sauce`],m:10,i:[[`date-syrup`,130,`ml`],[`water`,60,`ml`],[`ground-cardamom`,4,`g`]]}];var m={slug:i,id:n,country:`AE`,region:r,servings:8,minutes:85,title:u,text:s,steps:d};export{a as country,m as default,n as id,l as minutes,r as region,o as servings,i as slug,d as steps,s as text,u as title};